 {k:'parkKw', g:'關鍵字', label:'車位編號關鍵字', type:'list', def:'車編、車位編號、車位號、號車位', used:'BUY-15、RENT-12'},
 {k:'nameMode', g:'人名偵測', label:'人名偵測方式', type:'select', def:'medium', used:'BUY-14、RENT-13',
  opts:[['strict','① 姓名樣式（建議）'],['medium','② 姓名樣式＋姓氏連詞'],['loose','③ 百家姓單字（最寬鬆）']],
  note:'① 只抓有明確標記的姓名（稱謂、遮蔽符號、身分詞後接姓名）；② 另抓「姓氏＋1～2 字」，會多抓到沒有標記的姓名，誤報也較多；③ 出現任一百家姓單字即警示'},
 {k:'titleKw', g:'人名偵測', label:'稱謂（接在姓名後）', type:'list', def:'先生、小姐、女士、太太、君、夫人、老師、醫師、律師', note:'例如「王先生」「陳小姐」', used:'BUY-14、RENT-13'},
 {k:'roleKw', g:'人名偵測', label:'身分詞（接在姓名前）', type:'list', def:'買方、賣方、買受人、出賣人、承租人、出租人、權利人、義務人、代理人、所有權人、屋主、房東、房客、申報人、立約人、簽約人、繼承人、受贈人、贈與人、讓與人、受讓人、持有人、起造人、地主', note:'例如「承租人林美玲」「代理人：王大同」', used:'BUY-14、RENT-13'},
 {k:'surExclude', g:'人名偵測', label:'百家姓排除字（不視為姓氏）', type:'chars', def:'費管權利元應水易車金路申別關計萬於房方支公包步危蓋雙全常通和平成時家都向古山谷東文白石年', note:'一般用詞中常見的姓氏字，排除後可大幅減少誤報', used:'BUY-14、RENT-13'},
