/* ═══ 設定區 C：規則判斷式 ═══
   每個函式接到一筆資料 r 與參數 P，回傳 null（通過）或 {f:[欄位名稱], msg:'說明'}。
   取值：S(r,'欄位名稱') 取文字、N(r,'欄位名稱') 取數值。 */
const CHECKS={
 /* ───── 買賣 ───── */
 'BUY-01':(r,P)=>{const f=[],m=[];
   ['交易日期','登記完成日期','原因發生日期'].forEach(n=>{const s=S(r,n); if(!s)return;
     const d=rocDate(s); if(d===null){f.push(n);m.push(n+'格式錯誤（'+s+'）');}
     else if(d>P.baseDate){f.push(n);m.push(n+'為未來日期（'+s+'）');}});
   return f.length?{f,msg:m.join('；')}:null;},
 'BUY-02':r=>{const g=rocDate(S(r,'登記完成日期')); if(g===null)return null;
   const a=rocDate(S(r,'交易日期')), b=rocDate(S(r,'原因發生日期'));
   const f=['登記完成日期'],m=[];
   if(a!==null&&g<a){f.push('交易日期');m.push('交易日期 '+S(r,'交易日期'));}
   if(b!==null&&g<b){f.push('原因發生日期');m.push('原因發生日期 '+S(r,'原因發生日期'));}
   return m.length?{f,msg:'登記完成日期 '+S(r,'登記完成日期')+' 早於 '+m.join('、')}:null;},
 'BUY-03':r=>(S(r,'交易標的種類').includes('建物')&&N(r,'屋齡')===0&&!S(r,'預售屋申報書序號'))
   ?{f:['交易標的種類','屋齡','預售屋申報書序號'],msg:'屋齡為 0 但未填預售屋申報書序號'}:null,
 'BUY-04':r=>{const s=S(r,'預售屋申報書序號'); if(!s)return null;
   return ['B1','B2'].includes(s.slice(0,2).toUpperCase())?null:{f:['預售屋申報書序號'],msg:'預售屋序號「'+s+'」非 B1、B2 開頭'};},
 'BUY-05':r=>((N(r,'房地總價')||0)===0&&S(r,'申報案件狀態')!=='異常交易價格不揭露')
   ?{f:['房地總價','申報案件狀態'],msg:'房地總價為 0，但案件狀態為「'+(S(r,'申報案件狀態')||'空白')+'」'}:null,
 'BUY-06':(r,P)=>{if(!S(r,'預售屋申報書序號'))return null;
   const q=N(r,'預售屋申報總價'); if(q===null)return null;
   const p=N(r,'房地總價')||0, diff=Math.abs(p-q);
   if(q>0?diff/q*100<=P.priceDiffPct:diff===0)return null;
   if(diff===0)return null;
   const txt=S(r,'備註欄')+S(r,'備註內容(新制)');
   if(P.priceKw.some(k=>txt.includes(k)))return null;
   return {f:['房地總價','預售屋申報總價'],msg:'房地總價 '+fmtN(p)+'、預售屋申報總價 '+fmtN(q)+'，相差 '+fmtN(diff)+(q>0?'（'+(diff/q*100).toFixed(1)+'%）':'')+'，備註未載明原因'};},
 'BUY-07':(r,P)=>{const a=N(r,'停車位持分總面積')||0, b=N(r,'整合系統車位總面積')||0, d=Math.abs(a-b);
   return d>P.tolArea+1e-9?{f:['停車位持分總面積','整合系統車位總面積'],msg:'申報 '+a+'㎡、整合系統 '+b+'㎡，差 '+d.toFixed(2)+'㎡'}:null;},
 'BUY-08':r=>{const a=N(r,'交易筆棟數車位數量(申報主表)')||0, b=N(r,'移轉車位數(車位清冊)')||0;
   return a!==b?{f:['交易筆棟數車位數量(申報主表)','移轉車位數(車位清冊)'],msg:'主表 '+a+' 個、車位清冊 '+b+' 個'}:null;},
 'BUY-09':r=>{
   const code=S(r,'備註代碼(新制)').includes('0801'), kind=S(r,'交易標的種類')==='車位';
   if(!code&&!kind)return null;                      /* 兩種情形任一成立才檢核 */
   const f=['備註代碼(新制)','交易標的種類'],m=[];
   if(!kind){f.push('交易標的種類');m.push('交易標的種類為「'+(S(r,'交易標的種類')||'空白')+'」，應為車位');}
   if(blank(S(r,'門牌'))){f.push('門牌');m.push('門牌空白');}
   if(S(r,'建物型態')){f.push('建物型態');m.push('建物型態「'+S(r,'建物型態')+'」應為空');}
   const why=code&&kind?'備註代碼 0801 且標的種類為車位':(code?'備註代碼 0801（僅車位交易）':'交易標的種類為車位');
   return m.length?{f,msg:why+'，但 '+m.join('；')}:null;},
  'BUY-10':r=>(S(r,'交易標的種類').includes('建物')&&blank(S(r,'門牌')))
   ?{f:['交易標的種類','門牌'],msg:'標的「'+S(r,'交易標的種類')+'」含建物但門牌空白'}:null,
 'BUY-11':r=>bldCheck(r,true),
 'BUY-12':r=>(S(r,'建物型態')==='透天厝'&&(N(r,'申報土地持分總面積')||0)===0&&S(r,'申報案件狀態')!=='異常交易價格不揭露')
   ?{f:['建物型態','申報土地持分總面積','申報案件狀態'],msg:'透天厝但申報土地持分總面積為 0'}:null,
 'BUY-13':r=>{const h=piiId(S(r,'備註欄')+' '+S(r,'備註內容(新制)'));
   return h.length?{f:['備註欄','備註內容(新制)'],msg:'備註含 '+h.join('、')}:null;},
 'BUY-14':(r,P)=>{if(S(r,'申報案件狀態')==='資料揭露，備註欄不揭露')return null;
   const h=nameHit(S(r,'備註欄')+S(r,'備註內容(新制)'),P);
   return h?{f:['申報案件狀態','備註欄','備註內容(新制)'],msg:'備註疑似出現人名：'+h+'，案件狀態為「'+(S(r,'申報案件狀態')||'空白')+'」'}:null;},
 'BUY-15':(r,P)=>{if(S(r,'申報案件狀態')==='資料揭露，備註欄不揭露')return null;
   const txt=S(r,'備註欄')+S(r,'備註內容(新制)'), h=P.parkKw.filter(k=>txt.includes(k));
   return h.length?{f:['申報案件狀態','備註欄','備註內容(新制)'],msg:'備註含「'+h.join('、')+'」，案件狀態為「'+(S(r,'申報案件狀態')||'空白')+'」'}:null;},
 'BUY-16':r=>(S(r,'申報案件狀態')==='資料揭露，備註欄也揭露'&&!S(r,'備註代碼(新制)')&&!S(r,'備註欄'))
   ?{f:['申報案件狀態','備註代碼(新制)','備註欄'],msg:'案件狀態為備註欄揭露，但備註代碼與備註欄皆空白'}:null,
 'BUY-17':r=>phoneCheck(r),
 /* ───── 預售 ───── */
 'PRE-01':r=>bldCheck(r,false),
 'PRE-02':r=>shopFloor(r,'交易層次'),
 'PRE-03':(r,P)=>{const p=N(r,'停車位持分總面積')||0; if(p<=0)return null;
   const c=N(r,'共有部分(含車位)')||0;
