 'RENT-13':(r,P)=>{const h=nameHit(S(r,'備註欄'),P);
   return h?{f:['備註欄'],msg:'備註疑似出現人名：'+h}:null;},
 'RENT-14':r=>{const s=S(r,'出租型態(租賃用途為居住用始須勾選)');
   if(!['整棟(戶)出租','分層出租','獨立套房'].includes(s))return null;
