 'RENT-15':r=>phoneCheck(r),
};

/* ════════════════════ 以下為程式本體 ════════════════════ */
const $=id=>document.getElementById(id);
const esc=s=>String(s==null?'':s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const IDX={}; for(const t in COLS){IDX[t]={}; COLS[t].forEach((n,i)=>{(IDX[t][n]=IDX[t][n]||[]).push(i);});}
let CUR=null;  /* 目前判斷中的資料列（提供 S / N 取值） */
function S(r,n,k){const a=IDX[r.t][n]; if(!a)throw new Error(TYPES[r.t]+'沒有欄位「'+n+'」');
  const v=r.raw[a[Math.min(k||0,a.length-1)]]; return v==null?'':String(v).trim();}
function N(r,n,k){const s=S(r,n,k); if(s==='')return null;
  const x=Number(s.replace(/[,，\s]/g,'').replace(/%$/,'')); return isFinite(x)?x:null;}
const blank=s=>String(s||'').replace(/[　\s]/g,'')==='';
const fmtN=v=>Number(v).toLocaleString('zh-TW');
/* 民國 7 碼日期 → 可比較的整數（YYYMMDD）；格式錯誤回傳 null、空白回傳 null */
function rocDate(s){s=String(s||'').trim(); if(!s)return null;
  if(!/^\d{7}$/.test(s))return null;
  const y=+s.slice(0,3)+1911, m=+s.slice(3,5), d=+s.slice(5);
  if(m<1||m>12||d<1||d>31)return null;
  const dt=new Date(y,m-1,d); if(dt.getMonth()!==m-1||dt.getDate()!==d)return null;
  return +s;}
function rocBad(s){s=String(s||'').trim(); return s!==''&&rocDate(s)===null;}
function bldCheck(r,useElev){const ty=S(r,'建物型態'); if(!ty)return null;
  const fl=N(r,'總樓層數'), el=useElev?S(r,'有無電梯'):'';
  const f=['建物型態','總樓層數']; if(useElev)f.push('有無電梯');
  let m=null;
  if(ty.includes('住宅大樓')){ if(fl!==null&&fl<11)m='住宅大樓但總樓層 '+fl+' 層'; else if(useElev&&el&&el!=='Y')m='住宅大樓但有無電梯為 '+el; }
  else if(ty.includes('華廈')){ if(fl!==null&&fl>10)m='華廈但總樓層 '+fl+' 層'; else if(useElev&&el&&el!=='Y')m='華廈但有無電梯為 '+el; }
  else if(ty.includes('公寓')){ if(fl!==null&&fl>5)m='公寓但總樓層 '+fl+' 層'; else if(useElev&&el&&el!=='N')m='公寓但有無電梯為 '+el; }
  return m?{f,msg:m}:null;}
function hasFirstFloor(v){const s=String(v||'').trim();
  if(!s||s.includes('見其他'))return null;
  for(let tok of s.split(/[、,，;；]/)){tok=tok.trim();
    if(tok==='全'||['1','一','一層','一樓','1F','1f'].includes(tok))return true;
    const m=tok.match(/^(\d+)\s*[-~至]\s*(\d+)$/); if(m&&+m[1]<=1&&1<=+m[2])return true;}
  return false;}
function shopFloor(r,col){if(!S(r,'建物型態').includes('店面'))return null;
  return hasFirstFloor(S(r,col))===false?{f:['建物型態',col],msg:'店面但'+col+'為「'+S(r,col)+'」，未含一樓'}:null;}
function layout(s){s=String(s||''); if(!/房|廳|衛/.test(s))return null;
  const g=k=>{const m=s.match(new RegExp('(\\d+)\\s*'+k)); return m?+m[1]:0;};
  return {room:g('房'),hall:g('廳'),bath:g('衛')};}
const RE_PHONE=/(?:^|[^\d])09\d{2}[-\s]?\d{3}[-\s]?\d{3}(?:$|[^\d])/;
const RE_ID=/(?:^|[^A-Za-z0-9])([A-Z][1289]\d{8})(?!\d)/g;
function idValid(s){const L='ABCDEFGHJKLMNPQRSTUVXYWZIO'.indexOf(s[0]); if(L<0)return false;
  const n=L+10, w=[8,7,6,5,4,3,2,1]; let t=Math.floor(n/10)+(n%10)*9;
  for(let i=0;i<8;i++)t+=(+s[i+1])*w[i];
  return (t+(+s[9]))%10===0;}
function piiId(txt){const t=String(txt||''), out=[];
  if(RE_PHONE.test(t))out.push('手機號碼');
  RE_ID.lastIndex=0; let m, ids=[];
  while((m=RE_ID.exec(t))!==null){ if(idValid(m[1]))ids.push(m[1]); RE_ID.lastIndex=m.index+1; }
  if(ids.length)out.push('身分證字號');
  return out;}
const SURNAME='趙錢孫李周吳鄭王馮陳褚衛蔣沈韓楊朱秦尤許何呂施張孔曹嚴華金魏陶姜戚謝鄒喻柏水竇章雲蘇潘葛奚范彭郎魯韋昌馬苗鳳花方俞任袁柳酆鮑史唐費廉岑薛雷賀倪湯滕殷羅畢郝鄔安常樂于時傅皮卞齊康伍余元卜顧孟平黃和穆蕭尹姚邵湛汪祁毛禹狄米貝明臧計伏成戴談宋茅龐熊紀舒屈項祝董梁杜阮藍閔席季麻強賈路婁危江童顏郭梅盛林刁鍾徐邱駱高夏蔡田樊胡凌霍虞萬支柯昝管盧莫經房裘繆干解應宗丁宣賁鄧郁單杭洪包諸左石崔吉鈕龔程嵇邢滑裴陸榮翁荀羊於惠甄麴家封芮羿儲靳汲邴糜松井段富巫烏焦巴弓牧隗山谷車侯宓蓬全郗班仰秋仲伊宮寧仇欒暴甘鈄厲戎祖武符劉景詹束龍葉幸司韶郜黎薊薄印宿白懷蒲邰從鄂索咸籍賴卓藺屠蒙池喬陰鬱胥能蒼雙聞莘党翟譚貢勞逄姬申扶堵冉宰酈雍卻璩桑桂濮牛壽通邊扈燕冀郟浦尚農溫別莊晏柴瞿閻充慕連茹習宦艾魚容向古易慎戈廖庾終暨居衡步都耿滿弘匡國文寇廣祿闕東歐殳沃利蔚越夔隆師鞏厙聶晁勾敖融冷訾辛闞那簡饒空曾毋沙乜養鞠須豐巢關蒯相查後荊紅游竺權逯蓋益桓公';
const MASKCH='○〇Ｏ◯＊*Ｘ×χ？?x';   /* 遮蔽姓名用的符號 */
const NAME_PREFIX_OK='予給向由與和及為是的了也都並或至從對把將跟同讓售購買賣租';  /* 姓氏前可接的連接字 */
const HAN='[\\u4e00-\\u9fff]';
const reEsc=s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
/* 回傳命中說明字串，或 null。偵測方式見參數「人名偵測方式」 */
function nameHit(txt,P){
  const t=String(txt||''); if(!t)return null;
  for(const k of P.surExtra) if(k&&t.includes(k))return '自訂關鍵字「'+k+'」';
  const S2=[...SURNAME].filter(c=>!P.surExclude.includes(c)).join('');
  if(!S2)return null;
  let m;
  if(P.titleKw.length){
    m=t.match(new RegExp('['+SURNAME+']'+HAN+'{0,2}(?:'+P.titleKw.map(reEsc).join('|')+')'));
    if(m)return '姓名加稱謂「'+m[0]+'」';}
  m=t.match(new RegExp('['+S2+']'+HAN+'{0,1}['+MASKCH+']'));
  if(m)return '遮蔽的姓名「'+m[0]+'」';
  if(P.roleKw.length){
    m=t.match(new RegExp('(?:'+P.roleKw.map(reEsc).join('|')+')[為是:：，,、（(\\s]{0,3}['+S2+']'+HAN+'{1,2}'));
    if(m)return '身分詞後接姓名「'+m[0]+'」';}
  if(P.nameMode==='strict')return null;
  if(P.nameMode==='medium'){
    const re=new RegExp('['+S2+']'+HAN+'{1,2}','g');
    while((m=re.exec(t))!==null){
      const a=m.index, b=a+m[0].length;
      /* 姓氏前一個字若是中文（且不在連接詞內），多半是建案名或詞語的一部分，略過 */
      const prev=a>0?t[a-1]:'';
      if(prev&&/[\u4e00-\u9fff]/.test(prev)&&!NAME_PREFIX_OK.includes(prev)){re.lastIndex=a+1;continue;}
      const clash=P.nameStop.some(w=>{let i=t.indexOf(w);
        while(i>=0){ if(i<b&&i+w.length>a)return true; i=t.indexOf(w,i+1);} return false;});
      if(!clash)return '姓氏連詞「'+m[0]+'」';
      re.lastIndex=a+1;}
    return null;}
  for(const ch of t) if(S2.includes(ch))return '百家姓用字「'+ch+'」';
  return null;}
function phoneCols(t){const out=[]; COLS[t].forEach((n,i)=>{if(n.includes('電話'))out.push([n,i]);}); return out;}
/* 電話欄：出現中文字或英文字母即異常；「-」「、」等分隔符號不算 */
function phoneCheck(r){const bad=[],fi=[];
  for(const [n,i] of phoneCols(r.t)){const v=String(r.raw[i]==null?'':r.raw[i]).trim(); if(!v)continue;
    if(/[一-鿿A-Za-z]/.test(v)){bad.push(n+'「'+v+'」'); fi.push(i);}}
  return bad.length?{fi,f:[],msg:'電話欄位出現文字：'+bad.join('、')}:null;}

/* ── 狀態 ── */
const STORE='plvr-check-v3';
const state={page:'work',tab:'buy',files:[],sheets:[],recs:[],hits:[],ranAt:null,dirty:false,
  marks:{},params:{},ruleOn:{},
  f:{},  /* 每個類型的篩選條件 */
  rf:{grp:[],col:[],q:''},
  open:{}};
TKEYS.forEach(t=>state.f[t]={sev:'all',rule:'all',grp:'all',jd:'all',q:'',sort:'row',page:1});
META.rules.forEach(r=>{state.ruleOn[r.id]=r.on!=='停用';});
let P={};

function loadLS(){try{const o=JSON.parse(localStorage.getItem(STORE)||'null'); if(!o)return;
  if(o.marks)state.marks=o.marks; if(o.params)state.params=o.params;
  if(o.ruleOn)Object.assign(state.ruleOn,o.ruleOn);}catch(e){}}
function saveLS(){try{localStorage.setItem(STORE,JSON.stringify({marks:state.marks,params:state.params,ruleOn:state.ruleOn}));}catch(e){}}
loadLS();

function readParams(){const o={};
  for(const p of PARAMS){
    let v=state.params[p.k]; if(v===undefined||v===null||v==='')v=(p.type==='bool'?p.def:(p.def===''?'':p.def));
    if(p.type==='number')o[p.k]=Number(v);
    else if(p.type==='bool')o[p.k]=(v===true||v==='true');
    else if(p.type==='list')o[p.k]=String(v).split(/[、,，;；\s]+/).filter(Boolean);
    else if(p.type==='select')o[p.k]=String(v);
    else if(p.type==='chars')o[p.k]=String(v).replace(/[、,，;；\s]/g,'');
    else o[p.k]=String(v);
  }
  const d=o.baseDate?new Date(o.baseDate+'T00:00:00'):new Date();
  o.baseDate=(d.getFullYear()-1911)*10000+(d.getMonth()+1)*100+d.getDate();
  o.baseDateText=(d.getFullYear()-1911)+'/'+pad(d.getMonth()+1)+'/'+pad(d.getDate());
  return o;}
const pad=n=>String(n).padStart(2,'0');
function rocStamp(d){d=d||new Date();
  return (d.getFullYear()-1911)+pad(d.getMonth()+1)+pad(d.getDate())+'-'+pad(d.getHours())+pad(d.getMinutes());}
function toast(msg){const el=document.createElement('div'); el.className='td-toast'; el.textContent=msg;
  document.body.appendChild(el); setTimeout(()=>el.remove(),3600);}
function dl(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');
  a.href=u; a.download=name; document.body.appendChild(a); a.click(); a.remove(); setTimeout(()=>URL.revokeObjectURL(u),1500);}

/* ── 主頁面切換 ── */
ROOT.querySelector('nav.main').addEventListener('click',e=>{const b=e.target.closest('button[data-page]'); if(!b)return;
  state.page=b.dataset.page;
  ROOT.querySelectorAll('nav.main button').forEach(x=>x.toggleAttribute('aria-current',x===b));
  ROOT.querySelectorAll('nav.main button').forEach(x=>{if(x===b)x.setAttribute('aria-current','page'); else x.removeAttribute('aria-current');});
  $('pageWork').classList.toggle('hidden',state.page!=='work');
  $('pageConf').classList.toggle('hidden',state.page!=='conf');
  BODY.scrollTop=0;});

/* ── 類型頁籤 ── */
function renderTabs(){ROOT.querySelectorAll('.tabs').forEach(bar=>{
  const work=bar.dataset.bar==='work';
  bar.innerHTML=TKEYS.map(t=>{let badge='';
    if(work&&state.ranAt){const n=state.recs.filter(r=>r.t===t).length;
      const b=new Set(state.hits.filter(h=>h.rec.t===t&&mark(h).jd!=='ok').map(h=>h.rec.key)).size;
      badge='<span class="badge">'+n.toLocaleString()+' 筆</span>'+(b?'<span class="badge bad">異常 '+b+'</span>':'');}
    else if(!work){const a=META.rules.filter(r=>r.t===t), on=a.filter(r=>state.ruleOn[r.id]).length;
      badge='<span class="badge">'+on+' / '+a.length+'</span>';}
    return '<button class="tab" role="tab" type="button" data-t="'+t+'" aria-selected="'+(t===state.tab)+'">'+TYPES[t]+badge+'</button>';}).join('');});}
ROOT.addEventListener('click',e=>{const b=e.target.closest('.tab'); if(!b)return;
  state.tab=b.dataset.t; renderTabs(); renderResult(); renderRules();});

/* ══════════ 讀檔 ══════════ */
const drop=$('drop'), fileIn=$('file');
drop.onclick=()=>fileIn.click();
drop.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();fileIn.click();}};
['dragenter','dragover'].forEach(ev=>drop.addEventListener(ev,e=>{e.preventDefault();drop.classList.add('over');}));
['dragleave','drop'].forEach(ev=>drop.addEventListener(ev,e=>{e.preventDefault();drop.classList.remove('over');}));
drop.addEventListener('drop',e=>loadFiles(e.dataTransfer.files));
fileIn.onchange=()=>{loadFiles(fileIn.files); fileIn.value='';};

function detectType(sheetName,fileName,aoa){
  const head=aoa.slice(0,8).map(r=>(r||[]).map(v=>String(v==null?'':v).replace(/\s/g,'')).join('|')).join('|');
  if(head.includes('預售屋申報總價')||head.includes('移轉車位數'))return 'buy';
  if(head.includes('建造執照字號')||head.includes('解約申報書序號'))return 'pre';
  if(head.includes('租賃訂約日期')||head.includes('不動產租金總額'))return 'rent';
  for(const s of [sheetName,fileName]){if(/買賣/.test(s))return 'buy'; if(/預售/.test(s))return 'pre'; if(/租賃/.test(s))return 'rent';}
  const w=Math.max(0,...aoa.slice(0,60).map(r=>r?r.length:0));
  for(const t of TKEYS) if(Math.abs(w-COLS[t].length)<=2) return t;
  return 'skip';}
function extractRows(aoa){const start=Math.max(1,Number(readParams().startRow)||5)-1, out=[];
  for(let i=start;i<aoa.length;i++){const r=aoa[i];
    if(!r||!r.some(v=>String(v==null?'':v).trim()!==''))continue;
    if(String(r[0]||'').trim()==='申報書序號')continue;
    out.push({row:i+1,raw:r});}
  return out;}
async function loadFiles(list){
  for(const f of list){
    try{
      const buf=await f.arrayBuffer();
      const wb=XLSX.read(buf,{type:'array',cellStyles:true,cellDates:false,raw:false});
      state.files.push({name:f.name,buf});
      for(const sn of wb.SheetNames){
        const aoa=XLSX.utils.sheet_to_json(wb.Sheets[sn],{header:1,raw:true,defval:null,blankrows:true});
        if(!aoa.length)continue;
        const sh={file:f.name,sheet:sn,width:Math.max(0,...aoa.map(r=>r?r.length:0)),t:detectType(sn,f.name,aoa),aoa};
        sh.rows=extractRows(aoa);
        state.sheets.push(sh);
      }
    }catch(err){alert('無法讀取「'+f.name+'」：'+err.message);}
  }
  renderSheets();}
function renderSheets(){const tb=$('sheetTbl').querySelector('tbody');
  $('sheetTbl').classList.toggle('hidden',!state.sheets.length);
  tb.innerHTML=state.sheets.map((s,i)=>{
    const exp=COLS[s.t]?COLS[s.t].length:0;
    const w=exp&&Math.abs(s.width-exp)>2?' <span style="color:var(--err);font-size:12px">（應為 '+exp+' 欄）</span>':'';
    return '<tr><td>'+esc(s.file)+'</td><td>'+esc(s.sheet)+'</td><td>'+s.width+w+'</td><td>'+s.rows.length.toLocaleString()+
      '</td><td><select data-i="'+i+'" aria-label="判定類型">'+['buy','pre','rent','skip'].map(k=>'<option value="'+k+'"'+(k===s.t?' selected':'')+'>'+(TYPES[k]||'不檢核')+'</option>').join('')+
      '</select></td><td><button class="btn sm" data-del="'+i+'" type="button">移除</button></td></tr>';}).join('');
  const n=state.sheets.filter(s=>s.t!=='skip').reduce((a,s)=>a+s.rows.length,0);
  $('runBtn').disabled=!n;
  $('runMsg').textContent=n?'已載入 '+n.toLocaleString()+' 筆資料，可開始檢核。':'請先載入申報資料。';}
$('sheetTbl').addEventListener('change',e=>{if(e.target.dataset.i!=null){state.sheets[+e.target.dataset.i].t=e.target.value; renderSheets();}});
$('sheetTbl').addEventListener('click',e=>{const d=e.target.dataset.del;
  if(d!=null){const s=state.sheets.splice(+d,1)[0];
    if(!state.sheets.some(x=>x.file===s.file))state.files=state.files.filter(x=>x.name!==s.file);
    renderSheets();}});

/* ══════════ 執行檢核 ══════════ */
$('runBtn').onclick=()=>runChecks();
$('applyBtn').onclick=()=>{if(!state.sheets.length){toast('尚未載入申報資料');return;} runChecks(); state.page='work';
  ROOT.querySelectorAll('nav.main button').forEach(x=>{if(x.dataset.page==='work')x.setAttribute('aria-current','page'); else x.removeAttribute('aria-current');});
  $('pageWork').classList.remove('hidden'); $('pageConf').classList.add('hidden'); BODY.scrollTop=0;};
function runChecks(){
  $('runBtn').disabled=true; $('runMsg').textContent='檢核中…';
  setTimeout(()=>{
    try{ doRun(); }catch(err){ alert('檢核發生錯誤：'+err.message); console.error(err); }
    $('runBtn').disabled=false;
  },20);}
function doRun(){
  P=readParams();
  state.sheets.forEach(sh=>{sh.rows=extractRows(sh.aoa);});
  const recs=[],hits=[],errs={};
  for(const sh of state.sheets){
    if(!COLS[sh.t])continue;
    for(const x of sh.rows)
      recs.push({t:sh.t,file:sh.file,sheet:sh.sheet,row:x.row,raw:x.raw,
        key:sh.file+'|'+sh.sheet+'|'+x.row, hits:[], cellSev:{}, maxSev:null});
  }
  for(const rec of recs){
    for(const rule of META.rules){
      if(rule.t!==rec.t||!state.ruleOn[rule.id])continue;
      let res;
      try{ res=CHECKS[rule.id](rec,P); }catch(e){ errs[rule.id]=e.message; continue; }
      if(!res)continue;
      const fi=(res.fi||[]).concat((res.f||[]).map(n=>IDX[rec.t][n]?IDX[rec.t][n][0]:-1).filter(i=>i>=0));
      const h={rec,rule,msg:res.msg,fi:[...new Set(fi)],mk:rec.key+'|'+rule.id};
      rec.hits.push(h); hits.push(h);
      if(!rec.maxSev||SEV_RANK[rule.sev]>SEV_RANK[rec.maxSev])rec.maxSev=rule.sev;
    }
  }
  state.recs=recs; state.hits=hits; state.ranAt=new Date(); state.runErrs=Object.entries(errs);
  state.open={};
  TKEYS.forEach(t=>{state.f[t]={sev:'all',rule:'all',grp:'all',jd:'all',q:'',sort:'row',page:1};});
  const withData=TKEYS.filter(t=>recs.some(r=>r.t===t));
  if(withData.length&&!withData.includes(state.tab))state.tab=withData[0];
  state.dirty=false;
  $('resCard').classList.remove('hidden');
  renderStats(); renderTabs(); renderResult(); renderParamBanner();
  const bad=recs.filter(r=>r.hits.length).length;
  $('runMsg').textContent='檢核完成：'+recs.length.toLocaleString()+' 筆資料，'+bad.toLocaleString()+' 筆有異常。'+
    (state.runErrs.length?'（有 '+state.runErrs.length+' 項規則執行錯誤）':'');
  $('runTime').textContent='檢核時間 '+rocStamp(state.ranAt).replace('-',' ')+'　基準日 '+P.baseDateText;
  $('resCard').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}

/* ══════════ 統計 ══════════ */
function stat(list){const bad=list.filter(r=>r.hits.some(h=>mark(h).jd!=='ok'));
  return {rows:list.length,cases:new Set(list.map(r=>String(r.raw[0]||''))).size,bad:bad.length,
    e:bad.filter(r=>r.maxSev==='error').length,w:bad.filter(r=>r.maxSev==='warn').length,i:bad.filter(r=>r.maxSev==='info').length};}
function renderStats(){
  const a=stat(state.recs);
  let h='<div class="stats"><div class="col"><h4>本期合計</h4><div class="big">'+a.rows.toLocaleString()+'<small>筆</small></div><dl>'+
    '<dt>申報書件數</dt><dd>'+a.cases.toLocaleString()+' 件</dd><dt>異常筆數</dt><dd class="e">'+a.bad.toLocaleString()+'</dd>'+
    '<dt>異常比率</dt><dd>'+(a.rows?(a.bad/a.rows*100).toFixed(1):'0.0')+'%</dd></dl></div>';
  for(const t of TKEYS){const s=stat(state.recs.filter(r=>r.t===t));
    h+='<div class="col"><h4><span class="tag '+t+'">'+TYPES[t]+'</span></h4><div class="big">'+s.rows.toLocaleString()+'<small>筆</small></div><dl>'+
      '<dt>申報書件數</dt><dd>'+s.cases.toLocaleString()+' 件</dd><dt>異常筆數</dt><dd class="e">'+s.bad.toLocaleString()+'</dd>'+
      '<dt>error／warn／info</dt><dd>'+s.e+'／'+s.w+'／'+s.i+'</dd></dl></div>';}
  $('statsBox').innerHTML=h+'</div>';}

/* ══════════ 人工註記 ══════════ */
function mark(h){return state.marks[h.mk]||{jd:'pending',note:''};}
function setMark(h,o){const m=Object.assign({jd:'pending',note:''},state.marks[h.mk],o);
  if(m.jd==='pending'&&!m.note)delete state.marks[h.mk]; else state.marks[h.mk]=m;
  saveLS();}
const JD={pending:'待確認',bad:'有問題',ok:'無問題'};

/* ══════════ 結果畫面 ══════════ */
function addrOf(r){return r.t==='pre'?(S(r,'建案名稱')+' '+S(r,'交易標的(編號)')).trim():(S(r,'門牌')||S(r,'地段')+S(r,'代表地號'));}
const PAGE=60;
function renderResult(){
  const panel=$('resPanel'); if(!state.ranAt){panel.innerHTML='';return;}
  const t=state.tab, f=state.f[t];
  const all=state.hits.filter(h=>h.rec.t===t);
  if(!state.recs.some(r=>r.t===t)){panel.innerHTML='<div class="empty">本次沒有載入'+TYPES[t]+'資料。</div>';return;}
  const rules=[...new Set(all.map(h=>h.rule.id))].sort();
  const grps=[...new Set(all.map(h=>h.rule.grp))].sort();
  const cnt={}; all.forEach(h=>cnt[h.rule.id]=(cnt[h.rule.id]||0)+1);
  const nPend=all.filter(h=>mark(h).jd==='pending').length, nBad=all.filter(h=>mark(h).jd==='bad').length, nOk=all.filter(h=>mark(h).jd==='ok').length;
  let h='<div class="filters">'+
    '<select data-f="sev"><option value="all">所有嚴重度</option>'+['error','warn','info'].map(v=>'<option value="'+v+'"'+(f.sev===v?' selected':'')+'>'+v+'</option>').join('')+'</select>'+
    '<select data-f="grp"><option value="all">所有檢核分組</option>'+grps.map(g=>'<option value="'+esc(g)+'"'+(f.grp===g?' selected':'')+'>'+esc(g)+'</option>').join('')+'</select>'+
    '<select data-f="rule"><option value="all">所有規則</option>'+rules.map(id=>{const r=META.rules.find(x=>x.id===id);
      return '<option value="'+id+'"'+(f.rule===id?' selected':'')+'>'+id+'　'+esc(r.name.slice(0,22))+'（'+cnt[id]+'）</option>';}).join('')+'</select>'+
    '<select data-f="jd"><option value="all">所有判定</option><option value="pending"'+(f.jd==='pending'?' selected':'')+'>待確認（'+nPend+'）</option>'+
      '<option value="bad"'+(f.jd==='bad'?' selected':'')+'>有問題（'+nBad+'）</option><option value="ok"'+(f.jd==='ok'?' selected':'')+'>無問題（'+nOk+'）</option>'+
      '<option value="todo"'+(f.jd==='todo'?' selected':'')+'>待確認＋有問題（'+(nPend+nBad)+'）</option></select>'+
    '<input type="search" data-f="q" placeholder="搜尋序號、門牌、建案、行政區" value="'+esc(f.q)+'">'+
    '<button class="btn sm" data-bulk="bad" type="button">本頁全部設為有問題</button>'+
    '<button class="btn sm" data-bulk="pending" type="button">本頁全部回復待確認</button>'+
    '<span class="sp" id="resCount"></span></div>';
  if(state.runErrs&&state.runErrs.length)
    h+='<div class="banner bad" style="margin:0 0 10px">下列規則執行錯誤，未完成檢核：'+state.runErrs.map(([id,m])=>id+'（'+esc(m)+'）').join('、')+'</div>';
  h+='<div class="tbl-wrap"><table class="res"><thead><tr>'+
    '<th style="width:160px">人工判定</th>'+
    th('row','列號','width:60px')+th('case','申報書序號／標的','width:230px')+
    th('rule','規則','width:92px')+th('sev','嚴重度','width:72px')+
    '<th>異常說明</th><th style="width:22%">異常欄位值</th><th style="width:170px">備註</th>'+
    '</tr></thead><tbody id="resBody"></tbody></table></div><div class="pager" id="resPager"></div>';
  panel.innerHTML=h;
  renderRows();}
function th(key,label,style){const f=state.f[state.tab];
  const ar=f.sort===key?' <span class="ar">▲</span>':(f.sort==='-'+key?' <span class="ar">▼</span>':'');
  return '<th class="sortable" data-sort="'+key+'" style="'+(style||'')+'">'+label+ar+'</th>';}
function filtered(){const t=state.tab,f=state.f[t];
  let L=state.hits.filter(h=>h.rec.t===t);
  if(f.sev!=='all')L=L.filter(h=>h.rule.sev===f.sev);
  if(f.grp!=='all')L=L.filter(h=>h.rule.grp===f.grp);
  if(f.rule!=='all')L=L.filter(h=>h.rule.id===f.rule);
  if(f.jd!=='all')L=L.filter(h=>f.jd==='todo'?mark(h).jd!=='ok':mark(h).jd===f.jd);
  if(f.q){const q=f.q;
    L=L.filter(h=>String(h.rec.raw[0]||'').includes(q)||addrOf(h.rec).includes(q)||S(h.rec,'行政區').includes(q));}
  const dir=f.sort.startsWith('-')?-1:1, key=f.sort.replace(/^-/,'');
  L.sort((a,b)=>{let v=0;
    if(key==='row')v=a.rec.row-b.rec.row;
    else if(key==='case')v=String(a.rec.raw[0]).localeCompare(String(b.rec.raw[0]));
    else if(key==='rule')v=a.rule.id.localeCompare(b.rule.id);
    else if(key==='sev')v=SEV_RANK[b.rule.sev]-SEV_RANK[a.rule.sev];
    return v*dir||a.rec.row-b.rec.row||a.rule.id.localeCompare(b.rule.id);});
  return L;}
function renderRows(){
  const t=state.tab,f=state.f[t],L=filtered(),pages=Math.max(1,Math.ceil(L.length/PAGE));
  if(f.page>pages)f.page=pages;
  const cEl=$('resCount'); if(cEl)cEl.textContent='符合 '+L.length.toLocaleString()+' 項';
  const slice=L.slice((f.page-1)*PAGE,f.page*PAGE);
  const body=$('resBody'); if(!body)return;
  if(!slice.length){body.innerHTML='<tr><td colspan="8" class="empty">'+
    (state.hits.some(h=>h.rec.t===t)?'沒有符合篩選條件的項目。':TYPES[t]+'在目前啟用的規則下沒有異常。')+'</td></tr>';
    $('resPager').innerHTML=''; return;}
  let h='',prev=null,gi=0;
  slice.forEach(x=>{
    const m=mark(x), first=x.rec.key!==prev; if(first){gi^=1; prev=x.rec.key;}
    const cls='g'+gi+(first?' first':'')+(m.jd==='ok'?' dismissed':'')+(m.jd==='bad'?' confirmed':'');
    const cells=x.fi.slice(0,6).map(i=>'<span class="fv"><b>'+esc(COLS[t][i])+'：</b><span class="cell-'+x.rule.sev+'">'+
      (esc(disp(x.rec.raw[i]))||'（空白）')+'</span></span>').join('');
    h+='<tr class="'+cls+'" data-mk="'+esc(x.mk)+'">'+
      '<td class="jd"><span class="seg3">'+['pending','bad','ok'].map(v=>'<button type="button" data-jd="'+v+'" aria-pressed="'+(m.jd===v?'true':'false')+'">'+JD[v]+'</button>').join('')+'</span>'+
      (first&&x.rec.hits.length>1?'<div class="rowtools"><button class="btn sm" data-rowall="bad" type="button">整列'+x.rec.hits.length+'項有問題</button><button class="btn sm" data-rowall="ok" type="button">整列無問題</button></div>':'')+'</td>'+
      '<td>'+x.rec.row+'</td>'+
      '<td class="case">'+(first?'<b>'+esc(x.rec.raw[0])+'</b>'+(String(x.rec.raw[1]||'').trim()?' <small>分件 '+esc(x.rec.raw[1])+'</small>':'')+
        '<small>'+esc(S(x.rec,'行政區'))+' '+esc(addrOf(x.rec))+'</small><button class="expand" data-exp="'+esc(x.rec.key)+'" type="button">'+(state.open[x.rec.key]?'收合全部欄位':'展開全部欄位')+'</button>':'')+'</td>'+
      '<td><code>'+x.rule.id+'</code></td>'+
      '<td><span class="sev '+x.rule.sev+'">'+x.rule.sev+'</span></td>'+
      '<td class="msg"><b>'+esc(x.rule.name)+'</b><br>'+esc(x.msg)+'</td>'+
      '<td>'+cells+'</td>'+
      '<td><input class="note-in" data-note="'+esc(x.mk)+'" value="'+esc(m.note)+'" placeholder="人工備註"></td></tr>';
    if(first&&state.open[x.rec.key]){
      const sev={}; x.rec.hits.forEach(y=>{if(mark(y).jd!=='ok')y.fi.forEach(i=>{if(!sev[i]||SEV_RANK[y.rule.sev]>SEV_RANK[sev[i]])sev[i]=y.rule.sev;});});
      h+='<tr class="detail"><td colspan="8"><div class="kv">'+COLS[t].map((n,i)=>
        '<div class="'+(sev[i]||'')+'"><b title="'+esc(n)+'">'+esc(n)+'</b><span>'+esc(disp(x.rec.raw[i]))+'</span></div>').join('')+
        '</div><p style="margin:8px 0 0;font-size:12px;color:var(--muted)">來源：'+esc(x.rec.file)+'／'+esc(x.rec.sheet)+'／第 '+x.rec.row+' 列</p></td></tr>';}
  });
  body.innerHTML=h;
  $('resPager').innerHTML=pages>1?'<button class="btn sm" data-p="'+(f.page-1)+'"'+(f.page<=1?' disabled':'')+' type="button">上一頁</button><span>第 '+f.page+' / '+pages+' 頁</span><button class="btn sm" data-p="'+(f.page+1)+'"'+(f.page>=pages?' disabled':'')+' type="button">下一頁</button>':'';}
function disp(v){return v==null?'':String(v);}
function hitByMk(mk){return state.hits.find(h=>h.mk===mk);}

$('resPanel').addEventListener('change',e=>{const k=e.target.dataset.f;
  if(k&&k!=='q'){state.f[state.tab][k]=e.target.value; state.f[state.tab].page=1; renderResult();}});
$('resPanel').addEventListener('input',e=>{
  if(e.target.dataset.f==='q'){state.f[state.tab].q=e.target.value.trim(); state.f[state.tab].page=1; renderRows(); return;}
  const mk=e.target.dataset.note; if(mk){const h=hitByMk(mk); if(h)setMark(h,{note:e.target.value});}});
$('resPanel').addEventListener('click',e=>{
  const sortEl=e.target.closest('th[data-sort]');
  if(sortEl){const f=state.f[state.tab],k=sortEl.dataset.sort; f.sort=(f.sort===k?'-'+k:k); f.page=1; renderResult(); return;}
  const p=e.target.dataset.p; if(p){state.f[state.tab].page=+p; renderRows(); return;}
  const exp=e.target.dataset.exp; if(exp){state.open[exp]=!state.open[exp]; renderRows(); return;}
  const bulk=e.target.dataset.bulk;
  if(bulk){const f=state.f[state.tab],L=filtered().slice((f.page-1)*PAGE,f.page*PAGE);
    L.forEach(h=>setMark(h,{jd:bulk})); renderRows(); renderStats(); renderTabs(); return;}
  const tr=e.target.closest('tr[data-mk]'); if(!tr)return;
  const rowall=e.target.dataset.rowall;
  if(rowall){const h0=hitByMk(tr.dataset.mk); if(h0){h0.rec.hits.forEach(y=>setMark(y,{jd:rowall}));}
    renderRows(); renderStats(); renderTabs(); return;}
  const jd=e.target.dataset.jd;
  if(jd){const h=hitByMk(tr.dataset.mk); if(h){const cur=mark(h).jd; setMark(h,{jd:cur===jd?'pending':jd});}
    renderRows(); renderStats(); renderTabs();}});

/* ══════════ 註記匯出入 ══════════ */
$('expMark').onclick=()=>{
  const rows=Object.entries(state.marks).map(([k,v])=>{const p=k.split('|');
    return {file:p[0],sheet:p[1],row:+p[2],rule:p[3],jd:v.jd,note:v.note};});
  if(!rows.length){toast('目前沒有任何人工註記');return;}
  const data={產生時間:new Date().toISOString(),工具:'實價登錄檢核工具 v3',註記筆數:rows.length,註記:rows};
  dl(new Blob([JSON.stringify(data,null,1)],{type:'application/json'}),'10日檢核-異常案件註記-'+rocStamp()+'.json');
  toast('已匯出 '+rows.length+' 筆註記');};
$('impMark').onclick=()=>$('markFile').click();
$('markFile').onchange=async()=>{const f=$('markFile').files[0]; $('markFile').value=''; if(!f)return;
  try{const o=JSON.parse(await f.text());
    const rows=o.註記||o.marks||[]; if(!Array.isArray(rows))throw new Error('檔案內容不是註記格式');
    let n=0; rows.forEach(x=>{const k=[x.file,x.sheet,x.row,x.rule].join('|');
      if(x.jd||x.note){state.marks[k]={jd:x.jd||'pending',note:x.note||''}; n++;}});
    saveLS(); renderStats(); renderTabs(); renderResult();
    $('markMsg').textContent='已匯入 '+n+' 筆註記（'+f.name+'）';
    toast('已匯入 '+n+' 筆註記');
  }catch(err){alert('匯入失敗：'+err.message);}};

/* ══════════ 匯出全部案件清冊 ══════════ */
const FILL={error:'FDDAD6',warn:'FFE9A8',info:'D6E6FA'};
const FONTC={error:'9C1C12',warn:'6B4600',info:'17497F'};
const EXTRA=['檢核結果','異常項目數','最高嚴重度','命中規則','異常說明','人工判定','人工備註'];
/* ─ 匯出檔的統一格式（可自行調整） ─ */
const XFONT='新細明體';        /* 全表字型 */
const CLR_ORANGE='FFCC99';      /* 淺橘色 */
const CLR_PURPLE='CC99FF';      /* 紫色 */
const XTITLE='10日檢核結果匯出';/* A1 標題 */
/* 第 3、4 列標題要上底色的欄位範圍：[起欄, 迄欄, 色碼] */
const HEADFILL={
  buy:[['BG','BK',CLR_ORANGE],['BL','CK',CLR_PURPLE],['CS','CS',CLR_PURPLE]],
  pre:[['BR','CI',CLR_PURPLE]],
  rent:[['BJ','BY',CLR_PURPLE]],
};
function colIdx(s){let n=0; for(const ch of s.toUpperCase())n=n*26+(ch.charCodeAt(0)-64); return n-1;}
$('expAll').onclick=async()=>{
  if(!state.ranAt){toast('請先執行檢核');return;}
  try{
    const stamp=rocStamp();
    for(let fi=0;fi<state.files.length;fi++){
      const file=state.files[fi];
      const wb=XLSX.read(file.buf,{type:'array',cellStyles:true,cellDates:false,raw:false});
      const keep=[];
      for(const sn of wb.SheetNames){
        const sh=state.sheets.find(s=>s.file===file.name&&s.sheet===sn);
        if(!sh||sh.t==='skip'||!COLS[sh.t]){delete wb.Sheets[sn]; continue;}
        keep.push(sn); annotateSheet(wb.Sheets[sn],sh);
      }
      wb.SheetNames=keep;
      if(!keep.length)continue;
      const name='10日檢核-全部案件清冊-'+stamp+(state.files.length>1?'-'+(fi+1):'')+'.xlsx';
      const out=XLSX.write(wb,{bookType:'xlsx',type:'array',compression:true});
      dl(new Blob([out],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),name);
    }
    toast('已匯出全部案件清冊');
  }catch(err){alert('匯出失敗：'+err.message); console.error(err);}};

function annotateSheet(ws,sh){
  const t=sh.t, ref=XLSX.utils.decode_range(ws['!ref']);
  const base=Math.max(ref.e.c+1,COLS[t].length);          /* 檢核欄位從原始欄位右方開始 */
  const recs=state.recs.filter(r=>r.file===sh.file&&r.sheet===sh.sheet);
  const byRow={}; recs.forEach(r=>byRow[r.row]=r);
  /* 清理 SheetJS 讀入的欄寬屬性，避免匯出檔的 XML 不合規 */
  if(ws['!cols'])ws['!cols']=ws['!cols'].map(c=>c?{wch:Math.round((c.wch||c.width||10)*10)/10,hidden:!!c.hidden}:{wch:10});
  if(ws['!rows'])ws['!rows']=ws['!rows'].map(r=>r&&r.hpt?{hpt:r.hpt}:undefined);
  const HS={font:{name:'Microsoft JhengHei',sz:10,bold:true,color:{rgb:'FFFFFF'}},fill:{fgColor:{rgb:'2E5C80'}},
            alignment:{vertical:'center',horizontal:'center',wrapText:true},
            border:{top:bd(),bottom:bd(),left:bd(),right:bd()}};
  const put=(rr,cc,v,s)=>{const a=XLSX.utils.encode_cell({r:rr,c:cc});
    ws[a]={t:typeof v==='number'?'n':'s',v:v}; if(s)ws[a].s=s; return ws[a];};
  /* 第 3 列分組名稱、第 4 列欄位名稱 */
  put(2,base,'檢核結果（本工具產生）',{font:{name:'Microsoft JhengHei',sz:10,bold:true,color:{rgb:'FFFFFF'}},
      fill:{fgColor:{rgb:'17324D'}},alignment:{vertical:'center',horizontal:'center'}});
  EXTRA.forEach((n,i)=>put(3,base+i,n,HS));
  const merges=ws['!merges']||(ws['!merges']=[]);
  merges.push({s:{r:2,c:base},e:{r:2,c:base+EXTRA.length-1}});
  for(const rec of recs){
    const rr=rec.row-1;
    const live=rec.hits.filter(h=>mark(h).jd!=='ok');
    const all=rec.hits;
    let maxSev=null; live.forEach(h=>{if(!maxSev||SEV_RANK[h.rule.sev]>SEV_RANK[maxSev])maxSev=h.rule.sev;});
    const result=all.length===0?'通過':(live.length?'異常':'已排除');
    const vals=[result,live.length,maxSev||'',
      live.map(h=>h.rule.id).join('、'),
      all.map(h=>h.rule.id+' '+h.rule.name+'：'+h.msg+(mark(h).jd==='ok'?'（人工判定無問題）':'')).join('\n'),
      all.map(h=>h.rule.id+' '+JD[mark(h).jd]).join('\n'),
      all.filter(h=>mark(h).note).map(h=>h.rule.id+' '+mark(h).note).join('\n')];
    vals.forEach((v,i)=>{
      const s={font:{name:'Microsoft JhengHei',sz:10},alignment:{vertical:'top',wrapText:i>=4},
               border:{top:bd(),bottom:bd(),left:bd(),right:bd()}};
      if(i===0){s.fill={fgColor:{rgb:result==='異常'?(FILL[maxSev]||'FDDAD6'):(result==='通過'?'DDF1E4':'EFEFEF')}};
        s.font={name:'Microsoft JhengHei',sz:10,bold:true,color:{rgb:result==='異常'?(FONTC[maxSev]||'9C1C12'):(result==='通過'?'1E6B3F':'6B7A82')}};}
      if(i===2&&maxSev)s.font={name:'Microsoft JhengHei',sz:10,bold:true,color:{rgb:FONTC[maxSev]}};
      put(rr,base+i,v,s);});
    /* 異常欄位著色（已判定無問題者不標色） */
    const cs={}; live.forEach(h=>h.fi.forEach(i=>{if(!cs[i]||SEV_RANK[h.rule.sev]>SEV_RANK[cs[i]])cs[i]=h.rule.sev;}));
    for(const i in cs){const a=XLSX.utils.encode_cell({r:rr,c:+i});
      if(!ws[a])ws[a]={t:'s',v:''};
      const z=ws[a].z;
      ws[a].s={fill:{fgColor:{rgb:FILL[cs[i]]}},font:{name:'Microsoft JhengHei',sz:10,bold:true,color:{rgb:FONTC[cs[i]]}},
               alignment:{vertical:'top'}};
      if(z&&z!=='General')ws[a].s.numFmt=z;}
  }
  const endR=Math.max(ref.e.r,3), endC=base+EXTRA.length-1;
  ws['!ref']=XLSX.utils.encode_range({s:{r:0,c:0},e:{r:endR,c:endC}});
  const cols=ws['!cols']||(ws['!cols']=[]);
  while(cols.length<base)cols.push({wch:12});
  EXTRA.forEach((n,i)=>cols[base+i]={wch:i===4?52:i===5?20:i===6?26:i===3?20:10});
  /* ── 統一格式 ──
     全表新細明體、自動換列；第 3、4 列置中並上底色；第 4 列起加黑色框線；
     第 5 列起（資料列）靠左、上下置中；A1 為報表標題且不換列 */
  const fillMap={};
  (HEADFILL[t]||[]).forEach(([a,b,rgb])=>{for(let c=colIdx(a);c<=colIdx(b);c++)fillMap[c]=rgb;});
  const BK={style:'thin',color:{rgb:'000000'}}, BOX={top:BK,bottom:BK,left:BK,right:BK};
  if(ws['A1'])ws['A1'].v=XTITLE; else ws['A1']={t:'s',v:XTITLE};
  for(let r=0;r<=endR;r++)for(let c=0;c<=endC;c++){
    const a=XLSX.utils.encode_cell({r,c}); let cell=ws[a];
    const head=(r===2||r===3), body=(r>=3);      /* body：Excel 第 4 列起 */
    if(!cell){ if(!body)continue; cell=ws[a]={t:'s',v:''}; }
    const s=cell.s||{};
    s.font=Object.assign({},s.font,{name:XFONT,sz:(s.font&&s.font.sz)||10});
    s.alignment=Object.assign({},s.alignment,{wrapText:true,vertical:'center',horizontal:'left'});
    if(head){ s.alignment.horizontal='center';
      if(fillMap[c]!==undefined&&c<base)s.fill={fgColor:{rgb:fillMap[c]}}; }
    if(body)s.border=BOX;
    if(r===0&&c===0){ s.alignment.wrapText=false; s.font=Object.assign({},s.font,{bold:true,sz:12}); }
    if(cell.z&&cell.z!=='General'&&!s.numFmt)s.numFmt=cell.z;
    cell.s=s;
  }
}
function bd(){return {style:'thin',color:{rgb:'D0D7DC'}};}

/* ══════════ 檢核項目頁 ══════════ */
function colsOfType(t){const s=new Set(); META.rules.filter(r=>r.t===t).forEach(r=>r.f.forEach(c=>s.add(c)));
  return COLS[t].filter(c=>s.has(c));}
function renderRuleFilters(){
  const t=state.tab;
  const grps=[...new Set(META.rules.filter(r=>r.t===t).map(r=>r.grp))];
  const cols=colsOfType(t);
  const cCnt={}; cols.forEach(c=>cCnt[c]=META.rules.filter(r=>r.t===t&&r.f.includes(c)).length);
  const gCnt={}; grps.forEach(g=>gCnt[g]=META.rules.filter(r=>r.t===t&&r.grp===g).length);
  $('ruleFilters').innerHTML=
    msBtn('grp','檢核分組',grps,state.rf.grp,gCnt)+
    msBtn('col','涉及欄位',cols,state.rf.col,cCnt)+
    '<input type="search" data-rf="q" placeholder="搜尋規則代碼或名稱" value="'+esc(state.rf.q)+'">'+
    '<button class="btn sm" data-rfa="all" type="button">本頁全部啟用</button>'+
    '<button class="btn sm" data-rfa="none" type="button">本頁全部停用</button>'+
    '<button class="btn sm" data-rfa="clear" type="button">清除篩選</button>'+
    '<span class="sp" id="ruleCount"></span>';}
function msBtn(key,label,items,sel,cnt){
  const on=sel.length>0;
  return '<div class="ms" data-ms="'+key+'"><button type="button" class="'+(on?'on':'')+'">'+label+(on?'：已選 '+sel.length+' 項':'')+'</button>'+
    '<div class="pop hidden"><div class="hd"><input type="search" placeholder="搜尋"><button class="btn sm" data-msa="clear" type="button">清除</button></div>'+
    items.map(x=>'<label><input type="checkbox" value="'+esc(x)+'"'+(sel.includes(x)?' checked':'')+'><span>'+esc(x)+'</span><span class="c">'+(cnt[x]||0)+'</span></label>').join('')+
    '</div></div>';}
document.addEventListener('click',e=>{
  const ms=e.target.closest('.ms');
  ROOT.querySelectorAll('.ms .pop').forEach(p=>{if(!ms||p.parentNode!==ms)p.classList.add('hidden');});
  if(ms&&e.target.closest('.ms>button'))ms.querySelector('.pop').classList.toggle('hidden');});
$('ruleFilters').addEventListener('input',e=>{
  if(e.target.dataset.rf==='q'){state.rf.q=e.target.value.trim(); renderRules(); return;}
  const pop=e.target.closest('.pop');
  if(pop&&e.target.type==='search'){const q=e.target.value.trim();
    pop.querySelectorAll('label').forEach(l=>l.classList.toggle('hidden',q&&!l.textContent.includes(q)));}});
$('ruleFilters').addEventListener('change',e=>{
  const ms=e.target.closest('.ms'); if(!ms||e.target.type!=='checkbox')return;
  const key=ms.dataset.ms;
  state.rf[key]=[...ms.querySelectorAll('input[type=checkbox]:checked')].map(x=>x.value);
  ms.querySelector(':scope>button').classList.toggle('on',state.rf[key].length>0);
  ms.querySelector(':scope>button').firstChild.nodeValue=(key==='grp'?'檢核分組':'涉及欄位')+(state.rf[key].length?'：已選 '+state.rf[key].length+' 項':'');
  renderRules();});
$('ruleFilters').addEventListener('click',e=>{
  if(e.target.dataset.msa==='clear'){const ms=e.target.closest('.ms');
    ms.querySelectorAll('input[type=checkbox]').forEach(c=>c.checked=false);
    state.rf[ms.dataset.ms]=[]; ms.querySelector(':scope>button').classList.remove('on');
    ms.querySelector(':scope>button').firstChild.nodeValue=(ms.dataset.ms==='grp'?'檢核分組':'涉及欄位');
    renderRules(); return;}
  const a=e.target.dataset.rfa; if(!a)return;
  if(a==='clear'){state.rf={grp:[],col:[],q:''}; renderRuleFilters(); renderRules(); return;}
  visibleRules().forEach(r=>state.ruleOn[r.id]=(a==='all'));
  saveLS(); markDirty(); renderRules(); renderTabs();});
function visibleRules(){const t=state.tab,rf=state.rf;
  return META.rules.filter(r=>r.t===t
    &&(!rf.grp.length||rf.grp.includes(r.grp))
    &&(!rf.col.length||r.f.some(c=>rf.col.includes(c)))
    &&(!rf.q||r.id.toUpperCase().includes(rf.q.toUpperCase())||r.name.includes(rf.q)||r.cond.includes(rf.q)));}
function renderRules(){
  if(!$('ruleFilters').children.length||$('ruleFilters').dataset.t!==state.tab){
    renderRuleFilters(); $('ruleFilters').dataset.t=state.tab;}
  const L=visibleRules(), t=state.tab;
  const total=META.rules.filter(r=>r.t===t).length;
  const cEl=$('ruleCount'); if(cEl)cEl.textContent='顯示 '+L.length+' / '+total+' 項，啟用 '+META.rules.filter(r=>r.t===t&&state.ruleOn[r.id]).length+' 項';
  $('ruleList').innerHTML=L.length?L.map(r=>{
    const op=state.open['R'+r.id];
    return '<div class="rule'+(state.ruleOn[r.id]?'':' off')+'" data-id="'+r.id+'">'+
      '<div class="hd"><input type="checkbox" data-on="'+r.id+'"'+(state.ruleOn[r.id]?' checked':'')+' title="啟用此規則">'+
      '<span class="ar">'+(op?'▼':'▶')+'</span><code>'+r.id+'</code>'+
      '<span class="sev '+r.sev+'">'+r.sev+'</span><span class="nm">'+esc(r.name)+'</span>'+
      '<span class="gt">'+esc(r.grp)+'</span><span class="gt">'+r.f.length+' 欄</span>'+
      '<span class="cf '+r.conf+'">信心 '+r.conf+'</span></div>'+
      (op?'<div class="bd"><dl>'+
        '<dt>判斷條件</dt><dd>'+esc(r.cond)+'</dd>'+
        '<dt>比對欄位</dt><dd><div class="cols">'+r.f.map(c=>'<span>'+esc(c)+'（'+colLetter(t,c)+'）</span>').join('')+'</div></dd>'+
        (r.note?'<dt>備註</dt><dd>'+esc(r.note)+'</dd>':'')+
        (r.diff2?'<dt>說明</dt><dd>'+esc(r.diff2)+'</dd>':'')+
        (r.q?'<dt>待確認</dt><dd>'+esc(r.q)+'</dd>':'')+
        '<dt>原規則ID</dt><dd>'+esc(r.orig)+'</dd></dl></div>':'')+
      '</div>';}).join(''):'<div class="empty">沒有符合篩選條件的規則。</div>';}
function colLetter(t,name){const i=IDX[t][name]?IDX[t][name][0]:-1; if(i<0)return '-';
  let n=i+1,s=''; while(n){const m=(n-1)%26; s=String.fromCharCode(65+m)+s; n=(n-m-1)/26;} return s;}
$('ruleList').addEventListener('click',e=>{
  const box=e.target.closest('input[data-on]');
  if(box)return;
  const el=e.target.closest('.rule'); if(!el)return;
  const k='R'+el.dataset.id; state.open[k]=!state.open[k]; renderRules();});
$('ruleList').addEventListener('change',e=>{const id=e.target.dataset.on; if(!id)return;
  state.ruleOn[id]=e.target.checked; saveLS(); markDirty(); renderRules(); renderTabs();});

/* ══════════ 參數 ══════════ */
function renderParams(){
  const groups=[...new Set(PARAMS.map(p=>p.g))];
  $('paramGrid').innerHTML=groups.map(g=>PARAMS.filter(p=>p.g===g).map(p=>{
    const v=state.params[p.k]!==undefined?state.params[p.k]:p.def;
    let input;
    if(p.type==='select')input='<select data-p="'+p.k+'">'+p.opts.map(o=>'<option value="'+o[0]+'"'+(String(v)===o[0]?' selected':'')+'>'+esc(o[1])+'</option>').join('')+'</select>';
    else if(p.type==='list'||p.type==='chars')input='<textarea data-p="'+p.k+'" spellcheck="false">'+esc(v)+'</textarea>';
    else if(p.type==='date')input='<input type="date" data-p="'+p.k+'" value="'+esc(v)+'">';
    else input='<input type="number" data-p="'+p.k+'" value="'+esc(v)+'"'+(p.min!=null?' min="'+p.min+'"':'')+(p.step?' step="'+p.step+'"':'')+'>';
    return '<div class="pbox"><h4>'+esc(p.label)+'</h4>'+(p.note?'<p>'+esc(p.note)+'</p>':'')+input+
      (p.used?'<div class="used">使用規則：'+esc(p.used)+'</div>':'')+'</div>';}).join('')).join('');}
$('paramGrid').addEventListener('change',e=>{const k=e.target.dataset.p; if(!k)return;
  state.params[k]=e.target.value; saveLS(); markDirty();});
function markDirty(){state.dirty=true; renderParamBanner();}
function renderParamBanner(){
  $('paramBanner').innerHTML=state.dirty
    ? '<div class="banner warn">設定已變更，尚未套用到檢核結果。<span class="sp"></span><button class="btn sm" id="bApply" type="button">立即套用並重新檢核</button></div>'
    : (state.ranAt?'<div class="banner good">目前的檢核結果已採用這組設定（檢核時間 '+rocStamp(state.ranAt).replace('-',' ')+'）。</div>':'');
  const b=$('bApply'); if(b)b.onclick=()=>$('applyBtn').click();}
$('clrMark').onclick=()=>{const n=Object.keys(state.marks).length;
  if(!n){toast('目前沒有任何人工註記');return;}
  if(!confirm('將清除本機儲存的 '+n+' 筆人工判定與備註，且無法復原。建議先按「匯出目前註記」備份。確定清除嗎？'))return;
  state.marks={}; saveLS(); renderStats(); renderTabs(); renderResult(); $('markMsg').textContent='';
  toast('已清除 '+n+' 筆註記');};
$('expParam').onclick=()=>{
  const data={產生時間:new Date().toISOString(),工具:'實價登錄檢核工具 v3',
    參數:PARAMS.reduce((o,p)=>{o[p.k]=state.params[p.k]!==undefined?state.params[p.k]:p.def; return o;},{}),
    規則啟用:state.ruleOn};
  dl(new Blob([JSON.stringify(data,null,1)],{type:'application/json'}),'10日檢核-參數設定-'+rocStamp()+'.json');
  toast('已匯出參數設定');};
$('impParam').onclick=()=>$('paramFile').click();
$('paramFile').onchange=async()=>{const f=$('paramFile').files[0]; $('paramFile').value=''; if(!f)return;
  try{const o=JSON.parse(await f.text());
    if(o.參數||o.params)state.params=Object.assign({},o.參數||o.params);
    if(o.規則啟用||o.ruleOn)Object.assign(state.ruleOn,o.規則啟用||o.ruleOn);
    saveLS(); renderParams(); renderRules(); renderTabs(); markDirty();
    toast('已匯入參數設定（'+f.name+'）');
  }catch(err){alert('匯入失敗：'+err.message);}};
$('resetParam').onclick=()=>{if(!confirm('將參數與規則啟用狀態還原為預設值，確定嗎？'))return;
  state.params={}; META.rules.forEach(r=>{state.ruleOn[r.id]=r.on!=='停用';});
  saveLS(); renderParams(); renderRules(); renderTabs(); markDirty();};

/* ══════════ 啟動 ══════════ */
(function init(){
  const miss=META.rules.filter(r=>typeof CHECKS[r.id]!=='function').map(r=>r.id);
  const nOn=META.rules.filter(r=>state.ruleOn[r.id]).length;
  $('metaInfo').innerHTML='檢核規則 '+META.rules.length+' 項（買賣 '+META.rules.filter(r=>r.t==='buy').length+
    '、預售 '+META.rules.filter(r=>r.t==='pre').length+'、租賃 '+META.rules.filter(r=>r.t==='rent').length+'），目前啟用 '+nOn+' 項'+
    (miss.length?'<br><span style="color:#FFD2CC">缺少判斷式：'+miss.join('、')+'</span>':'');
  renderTabs(); renderParams(); renderRules(); renderParamBanner();
  const n=Object.keys(state.marks).length;
  if(n)$('markMsg').textContent='已從本機帶回上次的 '+n+' 筆人工註記，載入同一份資料後會自動對應。';
})();
}

export default {
  name: 'LahPrcTenday',
  mounted () {
    if (typeof window !== 'undefined') {
      window.XLSX = XLSX
    }
    try {
      initTenday()
    } catch (err) {
      console.error('initTenday error:', err)
    }
  }
}
</script>

<style scoped>
        /* ════════ 共用元件（四個工具一致；色票與 10日檢核相同） ════════ */
        body.app{--ui-ink:#17324D;--ui-ink2:#2A4A69;--ink:#17324D;--ink-2:#2A4A69;--paper:#EEF2F1;--line:#CFD8D6;--line-2:#E3E9E7;--soft:#F7FAF9;--text:#1B2429;--muted:#5A6A72;
            --err:#B42318;--err-bg:#FDECEA;--err-bd:#F3B8B2;--warn:#8A5A00;--warn-bg:#FFF1CC;--warn-bd:#EBCB7A;--info:#1D5FA8;--info-bg:#E6F0FB;--info-bd:#B5CFEE;--ok:#2E7D4F;--ok-bg:#E5F4EA;
            font-family:"Noto Sans TC","Microsoft JhengHei","PingFang TC","微軟正黑體",sans-serif;font-variant-numeric:tabular-nums}
        /* 工具外框 */
        .ui-frame{height:100%;display:flex;flex-direction:column;overflow:hidden;background:#fff;border:1px solid var(--line);border-radius:8px;box-shadow:0 1px 3px rgba(23,50,77,.06);font-size:15px;line-height:1.6;color:var(--text)}
        .ui-frame.hidden{display:none!important}
        .ui-head{display:flex;justify-content:space-between;align-items:center;gap:16px;min-height:62px;padding:10px 20px;background:var(--ui-ink);color:#fff;flex-shrink:0}
        .ui-head h2{margin:0;font-size:17px;font-weight:700;letter-spacing:.5px;line-height:1.4}
        .ui-head .sub{display:block;font-size:12px;color:#C3D3E0;line-height:1.5}
        .ui-headr{display:flex;align-items:center;gap:14px}
        .ui-head .meta{font-size:12px;color:#C3D3E0;text-align:right;line-height:1.5}
        .ui-close{border:1px solid #6F8AA6;background:transparent;color:#fff;border-radius:5px;padding:4px 12px;font-size:13px;cursor:pointer;white-space:nowrap;line-height:1.5}
        .ui-close:hover{background:var(--ui-ink2)}
        /* 頁籤（買賣實例檢核、10日檢核共用外觀） */
        .au-tabs,#tool-tenday-view nav.main{display:flex;gap:4px;padding:8px 20px 0;background:#E6ECEB;border-bottom:2px solid var(--ui-ink);flex-shrink:0}
        .au-tab,#tool-tenday-view nav.main button{border:1px solid var(--line);border-bottom:0;background:#D9E1E0;color:var(--muted);padding:7px 22px;border-radius:5px 5px 0 0;cursor:pointer;font-weight:700;font-size:14px;line-height:1.6;margin:0}
        .au-tab:hover,#tool-tenday-view nav.main button:hover{color:var(--ui-ink)}
        .au-tab.on,#tool-tenday-view nav.main button[aria-current=page]{background:var(--ui-ink);border-color:var(--ui-ink);color:#fff}
        .ui-body,.au-body,#tool-tenday-view .ui-body{flex:1;overflow:auto;background:var(--paper);padding:16px 20px 32px;scrollbar-gutter:stable}
        /* 卡片 */
        .ui-card{background:#fff;border:1px solid var(--line);border-radius:6px;margin-bottom:16px}
        .ui-card-h{margin:0;padding:12px 18px;border-bottom:1px solid var(--line-2);font-size:16.5px;font-weight:700;display:flex;align-items:center;gap:10px;flex-wrap:wrap;color:var(--text);line-height:1.5}
        .ui-card-h .n,.au-card-h .n{display:inline-grid;place-items:center;width:25px;height:25px;border-radius:50%;background:var(--ui-ink);color:#fff;font-size:13.5px;flex-shrink:0}
        .ui-card-h .aside{margin-left:auto;font-weight:400;font-size:13px;color:var(--muted)}
        .ui-card-b{padding:15px 18px}
        .ui-actions{display:flex;flex-wrap:wrap;gap:8px;align-items:center;padding:11px 18px;border-top:1px solid var(--line-2);background:var(--soft);border-radius:0 0 6px 6px}
        .ui-actions .note{color:var(--muted);font-size:13px}
        .ui-actions .sp{margin-left:auto}
        /* 按鈕 */
        .ui-btn{display:inline-flex;align-items:center;justify-content:center;gap:4px;border:1px solid var(--line);background:#fff;color:var(--text);border-radius:5px;padding:5px 12px;font-size:14px;line-height:1.5;cursor:pointer;white-space:nowrap}
        .ui-btn:hover{background:#F2F5F4}
        .ui-btn:disabled{opacity:.45;cursor:not-allowed}
        .ui-btn.primary{background:var(--ui-ink);border-color:var(--ui-ink);color:#fff;font-weight:600;padding:8px 22px}
        .ui-btn.primary:hover{background:var(--ui-ink2)}
        .ui-btn.primary:disabled{background:#8C9BA5;border-color:#8C9BA5;opacity:1}
        .ui-btn.dl{background:var(--ok);border-color:var(--ok);color:#fff;font-weight:600}
        .ui-btn.dl:hover{background:#256A42}
        .ui-btn.sm{padding:2px 9px;font-size:13px}
        .ui-btn.danger{color:var(--err);border-color:var(--err-bd)}
        /* 輸入 */
        .ui-input{border:1px solid var(--line);border-radius:5px;padding:5px 8px;font-size:14px;background:#fff;color:var(--text);line-height:1.5}
        .ui-input:focus,.ui-file:focus{outline:2px solid #9FB8D3;outline-offset:0;border-color:var(--ui-ink2)}
        .ui-file,.au-file{width:100%;height:38px;font-size:13.5px;border:1px solid var(--line);border-radius:5px;padding:4px 5px;background:#fff;color:var(--muted)}
        .ui-file::file-selector-button,.au-file::file-selector-button{margin-right:10px;padding:3px 12px;border:1px solid var(--line);background:var(--soft);border-radius:4px;color:var(--text);cursor:pointer;font-size:13px;font-weight:600}
        .ui-file::file-selector-button:hover,.au-file::file-selector-button:hover{background:#E6ECEB}
        /* 提示、標籤、狀態 */
        .ui-note{border:1px solid var(--info-bd);background:var(--info-bg);color:#17497F;border-radius:6px;padding:9px 13px;font-size:13.5px;line-height:1.6;margin-bottom:14px}
        .ui-note b{font-weight:700}
        .ui-badge{display:inline-block;font-size:12px;line-height:20px;padding:0 8px;border-radius:10px;font-weight:600;white-space:nowrap}
        .ui-badge.req{background:var(--err-bg);color:var(--err)}
        .ui-badge.opt{background:#E9EEEC;color:var(--muted)}
        .ui-status{margin:0 0 16px;padding:10px 14px;border-radius:6px;font-size:13.5px;white-space:pre-wrap;line-height:1.7}
        .ui-status.info{background:var(--soft);border:1px solid var(--line-2);color:var(--muted);font-family:Consolas,"Courier New",monospace}
        .ui-status.success{background:var(--ok-bg);border:1px solid #B7DFC4;color:#1E6B3F;font-weight:600}
        .ui-status.error{background:var(--err-bg);border:1px solid var(--err-bd);color:var(--err);font-weight:600}
        .ui-status.hidden{display:none}
        .sys-error{background:var(--err-bg);border:1px solid var(--err-bd);color:var(--err);padding:10px 14px;border-radius:6px;margin-bottom:16px;font-size:14px}
        /* 上傳檔案方塊 */
        .ui-filegrid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}
        .ui-filebox{display:flex;flex-direction:column;gap:8px;border:1px solid var(--line);border-radius:6px;padding:12px 14px;background:#fff}
        .ui-filebox.opt{border-style:dashed;background:var(--soft)}
        .fb-h{display:flex;align-items:center;gap:8px;font-weight:700;font-size:15px;color:var(--text)}
        .fb-h .ui-badge{margin-left:auto}
        .fb-spec{margin-top:auto;font-size:12.5px;color:var(--muted);line-height:1.6;border-top:1px dotted var(--line);padding-top:7px}
        .ui-msg{display:block;min-height:20px;font-size:13px;font-weight:600;color:var(--muted)}
        .ui-msg.ok{color:var(--ok)} .ui-msg.fail{color:var(--err)}
        /* 選項列、內嵌欄位 */
        .ui-radio{display:flex;flex-direction:column;gap:6px;border:1px solid var(--line-2);background:var(--soft);border-radius:6px;padding:10px 12px;margin-bottom:12px}
        .ui-radio label{display:flex;align-items:flex-start;gap:8px;cursor:pointer;font-size:14px}
        .ui-radio input{margin-top:5px;accent-color:var(--ui-ink)}
        .ui-radio b{font-weight:700;color:var(--ui-ink)}
        .ui-radio span{color:var(--muted)}
        .ui-inline{display:flex;flex-wrap:wrap;gap:10px 28px;align-items:center}
        .ui-inline label{display:flex;align-items:center;gap:8px;font-size:14px;font-weight:600}
        .ui-inline .ui-input{width:90px;text-align:center;font-weight:700}
        .ui-hint{font-size:12.5px;color:var(--muted);margin-top:8px}
        /* 統計列（同 10日檢核） */
        .ui-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));border:1px solid var(--line);border-radius:6px;overflow:hidden}
        .ui-stats .col{padding:11px 15px;border-left:1px solid var(--line-2)}
        .ui-stats .col:first-child{border-left:0;background:#F4F7FA}
        .ui-stats h4{margin:0 0 4px;font-size:13.5px;color:var(--muted);font-weight:500}
        .ui-stats .big{font-size:27px;font-weight:700;line-height:1.15;color:var(--ui-ink)}
        .ui-stats .big.bad{color:var(--err)}
        .ui-stats .big small{font-size:13px;font-weight:400;color:var(--muted);margin-left:3px}
        /* 資料表（同 10日檢核） */
        .ui-tablewrap{overflow-x:auto;border:1px solid var(--line);border-radius:6px;margin-top:14px}
        .ui-table{width:100%;border-collapse:collapse;font-size:13.5px}
        .ui-table th{background:#F4F7FA;font-weight:600;font-size:13px;text-align:left;padding:8px 10px;border-bottom:1px solid var(--line);white-space:nowrap}
        .ui-table td{padding:7px 10px;border-bottom:1px solid var(--line-2)}
        .ui-table .num{text-align:right}
        .ui-table tr.bad td{background:#FFF8F7}
        .ui-table td.hit{color:var(--err);font-weight:700}
        .ui-table td.zero{color:#A3ADB3}
        @media (max-width:1100px){.ui-filegrid{grid-template-columns:1fr}.ui-stats{grid-template-columns:repeat(2,minmax(0,1fr))}}


        /* ===== 功能E：10日檢核 專用樣式（全部限定在 #tool-tenday-view 內） ===== */
#tool-tenday-view{--ink:#17324D; --ink-2:#2A4A69; --paper:#EEF2F1; --panel:#FFF; --line:#CFD8D6; --line-2:#E3E9E7; --soft:#F7FAF9;
  --text:#1B2429; --muted:#5A6A72;
  --err:#B42318; --err-bg:#FDECEA; --err-bd:#F3B8B2;
  --warn:#8A5A00; --warn-bg:#FFF1CC; --warn-bd:#EBCB7A;
  --info:#1D5FA8; --info-bg:#E6F0FB; --info-bd:#B5CFEE;
  --ok:#2E7D4F; --ok-bg:#E5F4EA;
  --buy:#1F4E7A; --buy-bg:#E3ECF6; --pre:#5A3A82; --pre-bg:#EDE6F5; --rent:#1E6650; --rent-bg:#E2F1EC;
  --r:6px;}
#tool-tenday-view *{box-sizing:border-box}
#tool-tenday-view{margin:0}
#tool-tenday-view{background:var(--paper);color:var(--text);font:15px/1.6 "Noto Sans TC","Microsoft JhengHei","PingFang TC",sans-serif;font-variant-numeric:tabular-nums}
#tool-tenday-view button, #tool-tenday-view input, #tool-tenday-view select, #tool-tenday-view textarea{font:inherit;color:inherit}
#tool-tenday-view :focus-visible{outline:3px solid #F2B705;outline-offset:2px}
#tool-tenday-view code{font:12px/1.8 Consolas,"Courier New",monospace}
#tool-tenday-view .hidden{display:none!important}
#tool-tenday-view .td-main{max-width:1460px;margin:0 auto;padding:18px 24px 64px}
#tool-tenday-view section.card{background:var(--panel);border:1px solid var(--line);border-radius:var(--r);margin-bottom:16px}
#tool-tenday-view section.card>h2{margin:0;padding:12px 18px;border-bottom:1px solid var(--line-2);font-size:16.5px;display:flex;align-items:center;gap:10px;flex-wrap:wrap}
#tool-tenday-view section.card>h2 .n{display:inline-grid;place-items:center;width:25px;height:25px;border-radius:50%;background:var(--ink);color:#fff;font-size:13.5px}
#tool-tenday-view section.card>h2 .aside{margin-left:auto;font-weight:400;font-size:13px;color:var(--muted)}
#tool-tenday-view .body{padding:15px 18px}
#tool-tenday-view .btn{border:1px solid var(--line);background:#fff;border-radius:5px;padding:5px 12px;cursor:pointer;white-space:nowrap}
#tool-tenday-view .btn:hover{background:#F2F5F4}
#tool-tenday-view .btn:disabled{opacity:.45;cursor:not-allowed}
#tool-tenday-view .btn.primary{background:var(--ink);border-color:var(--ink);color:#fff;font-weight:600;padding:8px 20px}
#tool-tenday-view .btn.primary:hover{background:var(--ink-2)}
#tool-tenday-view .btn.primary:disabled{background:#8C9BA5;border-color:#8C9BA5;opacity:1}
#tool-tenday-view .btn.dl{background:var(--ok);border-color:var(--ok);color:#fff;font-weight:600}
#tool-tenday-view .btn.dl:hover{background:#256A42}
#tool-tenday-view .btn.sm{padding:2px 9px;font-size:13px}
#tool-tenday-view .drop{border:2px dashed #A8B8B5;border-radius:var(--r);padding:22px;text-align:center;cursor:pointer;background:var(--soft)}
#tool-tenday-view .drop.over{border-color:var(--ink);background:#E8EFF5}
#tool-tenday-view .drop strong{display:block;font-size:15.5px}
#tool-tenday-view .drop span{color:var(--muted);font-size:13px}
#tool-tenday-view table.sheets{width:100%;border-collapse:collapse;margin-top:12px;font-size:14px}
#tool-tenday-view table.sheets th, #tool-tenday-view table.sheets td{padding:6px 8px;border-bottom:1px solid var(--line-2);text-align:left}
#tool-tenday-view table.sheets th{color:var(--muted);font-weight:500;font-size:13px}
#tool-tenday-view table.sheets select{padding:3px 6px;border:1px solid var(--line);border-radius:4px;background:#fff}
#tool-tenday-view .stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));border:1px solid var(--line);border-radius:var(--r);overflow:hidden;margin-top:14px}
@media(max-width:860px){#tool-tenday-view .stats{grid-template-columns:repeat(2,minmax(0,1fr))}}
#tool-tenday-view .stats .col{padding:11px 15px;border-left:1px solid var(--line-2)}
#tool-tenday-view .stats .col:first-child{border-left:0;background:#F4F7FA}
#tool-tenday-view .stats h4{margin:0 0 4px;font-size:13.5px;display:flex;align-items:center;gap:7px;color:var(--muted)}
#tool-tenday-view .stats .big{font-size:27px;font-weight:700;line-height:1.15;color:var(--ink)}
#tool-tenday-view .stats .big small{font-size:13px;font-weight:400;color:var(--muted);margin-left:3px}
#tool-tenday-view .stats dl{margin:5px 0 0;display:grid;grid-template-columns:auto 1fr;gap:1px 10px;font-size:13px}
#tool-tenday-view .stats dt{color:var(--muted)}
#tool-tenday-view .stats dd{margin:0;text-align:right}
#tool-tenday-view .stats dd.e{color:var(--err);font-weight:600}
#tool-tenday-view .tabs{display:flex;gap:4px;padding:10px 18px 0;background:var(--soft);border-bottom:1px solid var(--line)}
#tool-tenday-view .tab{border:1px solid transparent;border-bottom:0;background:none;padding:8px 18px 9px;cursor:pointer;border-radius:6px 6px 0 0;font-weight:600;color:var(--muted);position:relative;top:1px;display:flex;align-items:center;gap:8px}
#tool-tenday-view .tab:hover{color:var(--ink)}
#tool-tenday-view .tab[aria-selected=true]{background:#fff;border-color:var(--line);color:var(--ink)}
#tool-tenday-view .tab[aria-selected=true]::before{content:"";position:absolute;left:-1px;right:-1px;top:-1px;height:3px;border-radius:6px 6px 0 0;background:var(--c)}
#tool-tenday-view .tab[data-t=buy]{--c:var(--buy)}
#tool-tenday-view .tab[data-t=pre]{--c:var(--pre)}
#tool-tenday-view .tab[data-t=rent]{--c:var(--rent)}
#tool-tenday-view .tab .badge{font-weight:400;font-size:12px;color:var(--muted);background:#E9EEEC;border-radius:10px;padding:0 8px;line-height:20px}
#tool-tenday-view .tab .badge.bad{background:var(--err-bg);color:var(--err);font-weight:600}
#tool-tenday-view .panel{padding:14px 18px}
#tool-tenday-view .tag{display:inline-block;white-space:nowrap;padding:0 8px;border-radius:10px;font-size:12px;line-height:20px}
#tool-tenday-view .tag.buy{background:var(--buy-bg);color:var(--buy)}
#tool-tenday-view .tag.pre{background:var(--pre-bg);color:var(--pre)}
#tool-tenday-view .tag.rent{background:var(--rent-bg);color:var(--rent)}
#tool-tenday-view .tag.skip{background:#EEE;color:#777}
#tool-tenday-view .sev{display:inline-block;text-align:center;border-radius:4px;font-size:12px;line-height:20px;padding:0 5px;font-weight:600}
#tool-tenday-view .sev.error{background:var(--err-bg);color:var(--err)}
#tool-tenday-view .sev.warn{background:var(--warn-bg);color:var(--warn)}
#tool-tenday-view .sev.info{background:var(--info-bg);color:var(--info)}
#tool-tenday-view .filters{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-bottom:10px}
#tool-tenday-view .filters select, #tool-tenday-view .filters input[type=search]{padding:5px 8px;border:1px solid var(--line);border-radius:5px;background:#fff;max-width:280px}
#tool-tenday-view .filters input[type=search]{min-width:200px}
#tool-tenday-view .filters .sp{margin-left:auto;color:var(--muted);font-size:13px}
#tool-tenday-view .ms{position:relative}
#tool-tenday-view .ms>button{border:1px solid var(--line);background:#fff;border-radius:5px;padding:5px 10px;cursor:pointer;display:flex;align-items:center;gap:6px}
#tool-tenday-view .ms>button.on{border-color:var(--ink);background:#EEF4FA;font-weight:600}
#tool-tenday-view .ms>button::after{content:"▾";color:var(--muted);font-size:11px}
#tool-tenday-view .ms .pop{position:absolute;z-index:40;top:calc(100% + 4px);left:0;width:330px;max-height:340px;overflow:auto;background:#fff;border:1px solid var(--line);border-radius:var(--r);box-shadow:0 8px 24px rgba(23,50,77,.16);padding:8px}
#tool-tenday-view .ms .pop .hd{display:flex;gap:6px;margin-bottom:6px}
#tool-tenday-view .ms .pop .hd input{flex:1;padding:4px 7px;border:1px solid var(--line);border-radius:4px}
#tool-tenday-view .ms .pop label{display:flex;gap:7px;align-items:flex-start;padding:3px 4px;border-radius:4px;cursor:pointer;font-size:13.5px;line-height:1.45}
#tool-tenday-view .ms .pop label:hover{background:#F2F6F9}
#tool-tenday-view .ms .pop label input{margin-top:3px}
#tool-tenday-view .ms .pop label .c{color:var(--muted);font-size:12px;margin-left:auto;white-space:nowrap}
#tool-tenday-view .actions{display:flex;flex-wrap:wrap;gap:8px;align-items:center;padding:11px 18px;border-top:1px solid var(--line-2);background:var(--soft);border-radius:0 0 var(--r) var(--r)}
#tool-tenday-view .actions .note{color:var(--muted);font-size:13px}
#tool-tenday-view .actions .sp{margin-left:auto}
#tool-tenday-view .tbl-wrap{overflow-x:auto;border:1px solid var(--line);border-radius:var(--r)}
#tool-tenday-view table.res{width:100%;border-collapse:collapse;font-size:13.5px;min-width:1150px}
#tool-tenday-view table.res th{background:#F4F7FA;font-weight:600;font-size:13px;text-align:left;padding:8px 9px;border-bottom:1px solid var(--line);white-space:nowrap}
#tool-tenday-view table.res th.sortable{cursor:pointer;user-select:none}
#tool-tenday-view table.res th.sortable:hover{color:var(--ink);text-decoration:underline}
#tool-tenday-view table.res th .ar{color:var(--ink);font-size:11px}
#tool-tenday-view table.res td{padding:7px 9px;border-bottom:1px solid var(--line-2);vertical-align:top}
#tool-tenday-view table.res tr.g0 td{background:#fff}
#tool-tenday-view table.res tr.g1 td{background:#FAFCFD}
#tool-tenday-view table.res tr.first td{border-top:2px solid var(--line)}
#tool-tenday-view table.res tr.dismissed td{opacity:.5}
#tool-tenday-view table.res tr.confirmed td.jd{background:var(--err-bg)}
#tool-tenday-view td.case{font-size:13px}
#tool-tenday-view td.case b{font-weight:600}
#tool-tenday-view td.case small{color:var(--muted);display:block;font-size:12px}
#tool-tenday-view .msg{line-height:1.5}
#tool-tenday-view .msg code{color:var(--muted);margin-right:4px}
#tool-tenday-view .fv{display:block;font-size:12.5px;margin:1px 0}
#tool-tenday-view .fv b{font-weight:500;color:var(--muted)}
#tool-tenday-view .cell-error{background:var(--err-bg);color:var(--err);font-weight:600;padding:0 4px;border-radius:3px}
#tool-tenday-view .cell-warn{background:var(--warn-bg);color:var(--warn);font-weight:600;padding:0 4px;border-radius:3px}
#tool-tenday-view .cell-info{background:var(--info-bg);color:var(--info);font-weight:600;padding:0 4px;border-radius:3px}
#tool-tenday-view .jd{white-space:nowrap}
#tool-tenday-view .seg3{display:inline-flex;border:1px solid var(--line);border-radius:5px;overflow:hidden}
#tool-tenday-view .seg3 button{border:0;border-left:1px solid var(--line);background:#fff;padding:3px 9px;cursor:pointer;font-size:12.5px;line-height:1.5}
#tool-tenday-view .seg3 button:first-child{border-left:0}
